from parent_ops import *
id='local096'
query(id,'parent-normalization',"SELECT 'cast' table_name,COUNT(*) rows,COUNT(DISTINCT MID||'|'||PID) pairs,COUNT(DISTINCT TRIM(MID)||'|'||TRIM(PID)) normalized_pairs,SUM(MID!=TRIM(MID)) padded_mid,SUM(PID!=TRIM(PID)) padded_pid FROM M_Cast UNION ALL SELECT 'Person',COUNT(*),COUNT(DISTINCT PID),COUNT(DISTINCT TRIM(PID)),SUM(PID!=TRIM(PID)),SUM(PID!=TRIM(PID)) FROM Person")
base="""WITH persons AS MATERIALIZED (SELECT PID,MAX(CASE WHEN Gender='Female' THEN 0 ELSE 1 END) bad FROM Person GROUP BY PID), cast_rows AS MATERIALIZED (SELECT DISTINCT TRIM(MID) mid,TRIM(PID) pid FROM M_Cast), cast_flags AS MATERIALIZED (SELECT c.mid,COUNT(*) actors,MAX(COALESCE(p.bad,1)) bad FROM cast_rows c LEFT JOIN persons p ON c.pid=p.PID GROUP BY c.mid), movie_flags AS (SELECT m.MID,m.title,CAST(substr(m.year,-4) AS INTEGER) year,COALESCE(c.actors,0) actors,COALESCE(c.bad,0) bad FROM Movie m LEFT JOIN cast_flags c ON m.MID=c.mid) """
query(id,'parent-cast-integrity',base+"SELECT COUNT(*) movies,SUM(actors=0) empty_cast,SUM(actors>0 AND bad=0) female_only,SUM(actors>0 AND bad>0) rejected FROM movie_flags")
query(id,'parent-female-examples',base+"SELECT MID,title,year,actors FROM movie_flags WHERE actors>0 AND bad=0 ORDER BY year,MID",100)
query(id,'parent-empty-cast-by-year',base+"SELECT year,COUNT(*) total,SUM(actors=0) empty_cast,SUM(actors>0 AND bad=0) female_only FROM movie_flags GROUP BY year ORDER BY year",150)
query(id,'parent-key-conflicts',"SELECT PID,COUNT(*) n,COUNT(DISTINCT Gender) genders,GROUP_CONCAT(DISTINCT Gender) values_seen FROM Person GROUP BY PID HAVING COUNT(*)>1 ORDER BY genders DESC,PID LIMIT 15")
