spec(id,{'population.entity':req({'name':'films','keyColumns':['Movie.MID']},'percentage of films'),'population.eligibility':assume('分母所有电影；分子至少一cast且所有Person明确Female，空cast排除分子'),'population.conditions':assume(['分子排除Male、None、SQL NULL或无法连接演员；演员身份外围空白清理']),'population.time':req('全年份；CAST(substr(Movie.year,-4) AS INTEGER)','taking the last 4 characters and converting to a number'),'measure.formula':assume({'op':'custom','description':'先按电影聚合cast资格，再按年100*符合电影数/全部电影数；重复Person同PID保守合并，TRIM cast MID/PID'}),'measure.countGrain':assume('一部MID一票'),'measure.denominator':req('该年全部Movie','the total number of movies in that year'),'grouping':req(['year'],'For each year'),'selection':'n/a','output':req({'rowMode':'grouped','columns':['year','total_movies','female_percentage']},'display the year, the total number of movies in that year, and the percentage')})
final_freeze(id,base+'SELECT year,COUNT(*) total_movies,100.0*SUM(actors>0 AND bad=0)/COUNT(*) female_percentage FROM movie_flags GROUP BY year ORDER BY year',{'algorithm':'TRIM cast identity; duplicate Person group with any non-Female disqualifies; all Movie denominator; nonempty cast numerator; exact year suffix','assumptions':['空cast不满足had exclusively female actors；重复Person保守合并','外围空白键规范化'],'limitations':['同PID冲突和空cast解释单独保留备选']})
